  drag2.element.style.zIndex = "140";
  drag2.element.style.transform = `translate(calc(-50% + ${drag2.baseX}px + ${pullX}px), calc(${drag2.baseY}px + ${pullY}px)) rotate(${drag2.baseRot + tilt}deg) scale(${desktopPointer ? 1.18 : 1.16})`;
